import { relations, sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  customType,
  datetime,
  decimal,
  index,
  int,
  json,
  mysqlEnum,
  mysqlTable,
  text,
  uniqueIndex,
  varchar,
} from "drizzle-orm/mysql-core";

/**
 * RomeoVille Records schema.
 *
 * The application is metadata driven: user defined "registers" hold dynamic
 * field definitions and records whose values are stored in a typed value table.
 * No physical table is ever generated at runtime and no SQL is built from
 * user supplied column names.
 *
 * All identifiers are UUID v4 strings generated by the application so that
 * records cannot be enumerated by guessing sequential ids.
 */

export const ROLES = ["super_admin", "admin", "editor", "viewer"] as const;
export type Role = (typeof ROLES)[number];

export const USER_STATUSES = ["pending", "active", "disabled"] as const;
export type UserStatus = (typeof USER_STATUSES)[number];

export const FIELD_TYPES = [
  "text",
  "long_text",
  "integer",
  "decimal",
  "date",
  "datetime",
  "boolean",
  "select",
  "multi_select",
  "email",
  "phone",
  "url",
] as const;
export type FieldType = (typeof FIELD_TYPES)[number];

const id = () => varchar("id", { length: 36 }).primaryKey();

/**
 * LONGBLOB column (up to 4 GiB) mapped to Node `Buffer`. Drizzle's `binary()`
 * builder is typed as a `string` column with a 255-byte practical limit, so
 * the workbook chunk payloads use an explicit custom type instead.
 */
const longBlob = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => "longblob",
});

const createdAt = () =>
  datetime("created_at", { mode: "date", fsp: 3 }).notNull().default(sql`CURRENT_TIMESTAMP(3)`);
const updatedAt = () =>
  datetime("updated_at", { mode: "date", fsp: 3 })
    .notNull()
    .default(sql`CURRENT_TIMESTAMP(3)`)
    .$onUpdate(() => new Date());

export const users = mysqlTable(
  "users",
  {
    id: id(),
    email: varchar("email", { length: 255 }).notNull(),
    fullName: varchar("full_name", { length: 160 }),
    passwordHash: varchar("password_hash", { length: 255 }),
    role: mysqlEnum("role", ROLES).notNull().default("viewer"),
    status: mysqlEnum("status", USER_STATUSES).notNull().default("pending"),
    lastLoginAt: datetime("last_login_at", { mode: "date", fsp: 3 }),
    lastLoginIp: varchar("last_login_ip", { length: 64 }),
    passwordUpdatedAt: datetime("password_updated_at", { mode: "date", fsp: 3 }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deactivatedAt: datetime("deactivated_at", { mode: "date", fsp: 3 }),
  },
  (table) => [uniqueIndex("users_email_unique").on(table.email)],
);

export const sessions = mysqlTable(
  "sessions",
  {
    id: id(),
    userId: varchar("user_id", { length: 36 })
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    tokenHash: varchar("token_hash", { length: 64 }).notNull(),
    expiresAt: datetime("expires_at", { mode: "date", fsp: 3 }).notNull(),
    createdAt: createdAt(),
    lastSeenAt: datetime("last_seen_at", { mode: "date", fsp: 3 }).notNull().default(sql`CURRENT_TIMESTAMP(3)`),
    ip: varchar("ip", { length: 64 }),
    userAgent: varchar("user_agent", { length: 400 }),
    revokedAt: datetime("revoked_at", { mode: "date", fsp: 3 }),
  },
  (table) => [
    uniqueIndex("sessions_token_hash_unique").on(table.tokenHash),
    index("sessions_user_id_idx").on(table.userId),
  ],
);

export const passwordResetTokens = mysqlTable(
  "password_reset_tokens",
  {
    id: id(),
    userId: varchar("user_id", { length: 36 })
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    tokenHash: varchar("token_hash", { length: 64 }).notNull(),
    expiresAt: datetime("expires_at", { mode: "date", fsp: 3 }).notNull(),
    consumedAt: datetime("consumed_at", { mode: "date", fsp: 3 }),
    requestIp: varchar("request_ip", { length: 64 }),
    createdAt: createdAt(),
  },
  (table) => [
    uniqueIndex("password_reset_tokens_hash_unique").on(table.tokenHash),
    index("password_reset_tokens_user_idx").on(table.userId),
  ],
);

export const invitations = mysqlTable(
  "invitations",
  {
    id: id(),
    kind: mysqlEnum("kind", ["staff", "bootstrap"]).notNull().default("staff"),
    email: varchar("email", { length: 255 }).notNull(),
    fullName: varchar("full_name", { length: 160 }),
    message: text("message"),
    role: mysqlEnum("role", ROLES).notNull(),
    tokenHash: varchar("token_hash", { length: 64 }).notNull(),
    status: mysqlEnum("status", ["pending", "accepted", "revoked", "expired"])
      .notNull()
      .default("pending"),
    invitedByUserId: varchar("invited_by_user_id", { length: 36 }).references(() => users.id, { onDelete: "set null" }),
    expiresAt: datetime("expires_at", { mode: "date", fsp: 3 }).notNull(),
    sentAt: datetime("sent_at", { mode: "date", fsp: 3 }),
    resendCount: int("resend_count").notNull().default(0),
    acceptedAt: datetime("accepted_at", { mode: "date", fsp: 3 }),
    revokedAt: datetime("revoked_at", { mode: "date", fsp: 3 }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex("invitations_token_hash_unique").on(table.tokenHash),
    index("invitations_email_status_idx").on(table.email, table.status),
  ],
);

export const registers = mysqlTable(
  "registers",
  {
    id: id(),
    name: varchar("name", { length: 160 }).notNull(),
    slug: varchar("slug", { length: 180 }).notNull(),
    description: text("description"),
    category: varchar("category", { length: 120 }),
    icon: varchar("icon", { length: 64 }),
    color: varchar("color", { length: 32 }),
    status: mysqlEnum("status", ["active", "archived"]).notNull().default("active"),
    /** Atomic per-register serial counter used for display "S/N" values. */
    serialCounter: bigint("serial_counter", { mode: "number", unsigned: true })
      .notNull()
      .default(0),
    recordCount: int("record_count").notNull().default(0),
    createdByUserId: varchar("created_by_user_id", { length: 36 }).references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    archivedAt: datetime("archived_at", { mode: "date", fsp: 3 }),
  },
  (table) => [uniqueIndex("registers_slug_unique").on(table.slug)],
);

export const registerFields = mysqlTable(
  "register_fields",
  {
    id: id(),
    registerId: varchar("register_id", { length: 36 })
      .notNull()
      .references(() => registers.id, { onDelete: "cascade" }),
    fieldKey: varchar("field_key", { length: 64 }).notNull(),
    name: varchar("name", { length: 160 }).notNull(),
    fieldType: mysqlEnum("field_type", FIELD_TYPES).notNull(),
    required: boolean("required").notNull().default(false),
    helpText: varchar("help_text", { length: 300 }),
    options: json("options"),
    defaultValue: varchar("default_value", { length: 500 }),
    displayOrder: int("display_order").notNull().default(0),
    showInTable: boolean("show_in_table").notNull().default(true),
    showInCard: boolean("show_in_card").notNull().default(true),
    editable: boolean("editable").notNull().default(true),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex("register_fields_key_unique").on(table.registerId, table.fieldKey),
    index("register_fields_register_idx").on(table.registerId, table.displayOrder),
  ],
);

export const records = mysqlTable(
  "records",
  {
    id: id(),
    registerId: varchar("register_id", { length: 36 })
      .notNull()
      .references(() => registers.id, { onDelete: "cascade" }),
    serial: bigint("serial", { mode: "number", unsigned: true }).notNull(),
    status: mysqlEnum("status", ["active", "archived"]).notNull().default("active"),
    dataVersion: int("data_version").notNull().default(1),
    /**
     * Denormalized, single-column concatenation of the record's text values.
     * Maintained on every write so search can scan one row per record instead
     * of joining the value table per cell.
     */
    searchText: text("search_text"),
    createdByUserId: varchar("created_by_user_id", { length: 36 }).references(() => users.id, { onDelete: "set null" }),
    updatedByUserId: varchar("updated_by_user_id", { length: 36 }).references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: datetime("deleted_at", { mode: "date", fsp: 3 }),
  },
  (table) => [
    uniqueIndex("records_register_serial_unique").on(table.registerId, table.serial),
    index("records_register_updated_idx").on(table.registerId, table.status, table.updatedAt),
  ],
);

export const recordValues = mysqlTable(
  "record_values",
  {
    id: id(),
    recordId: varchar("record_id", { length: 36 })
      .notNull()
      .references(() => records.id, { onDelete: "cascade" }),
    fieldId: varchar("field_id", { length: 36 })
      .notNull()
      .references(() => registerFields.id, { onDelete: "cascade" }),
    /**
     * Typed storage: exactly one of the value_* columns is populated,
     * matching the owning field's type. TEXT holds up to 16k characters.
     */
    valueText: text("value_text"),
    valueNumber: decimal("value_number", { precision: 24, scale: 8, mode: "number" }),
    valueDate: datetime("value_date", { mode: "date", fsp: 3 }),
    valueBoolean: boolean("value_boolean"),
    valueJson: json("value_json"),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex("record_values_record_field_unique").on(table.recordId, table.fieldId),
    // NOTE: text filters narrow through field_id first; a composite index with
    // value_text would exceed MySQL/TiDB's 3072 byte key limit under utf8mb4.
    index("record_values_field_idx").on(table.fieldId),
    index("record_values_field_number_idx").on(table.fieldId, table.valueNumber),
    index("record_values_field_date_idx").on(table.fieldId, table.valueDate),
  ],
);

export const registerViews = mysqlTable(
  "register_views",
  {
    id: id(),
    registerId: varchar("register_id", { length: 36 })
      .notNull()
      .references(() => registers.id, { onDelete: "cascade" }),
    name: varchar("name", { length: 160 }).notNull(),
    ownerUserId: varchar("owner_user_id", { length: 36 })
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    config: json("config").notNull(),
    isShared: boolean("is_shared").notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [index("register_views_register_idx").on(table.registerId, table.ownerUserId)],
);

export const registerAccess = mysqlTable(
  "register_access",
  {
    id: id(),
    registerId: varchar("register_id", { length: 36 })
      .notNull()
      .references(() => registers.id, { onDelete: "cascade" }),
    targetType: mysqlEnum("target_type", ["role", "user"]).notNull(),
    targetId: varchar("target_id", { length: 120 }).notNull(),
    canView: boolean("can_view").notNull().default(false),
    canCreate: boolean("can_create").notNull().default(false),
    canEdit: boolean("can_edit").notNull().default(false),
    canDelete: boolean("can_delete").notNull().default(false),
    canImport: boolean("can_import").notNull().default(false),
    canExport: boolean("can_export").notNull().default(false),
    createdByUserId: varchar("created_by_user_id", { length: 36 }).references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex("register_access_target_unique").on(
      table.registerId,
      table.targetType,
      table.targetId,
    ),
  ],
);

export const importJobs = mysqlTable(
  "import_jobs",
  {
    id: id(),
    kind: mysqlEnum("kind", ["new_register", "existing_register"]).notNull(),
    status: mysqlEnum("status", [
      "draft",
      "pending",
      "processing",
      "completed",
      "partial",
      "failed",
      "cancelled",
    ])
      .notNull()
      .default("draft"),
    targetRegisterId: varchar("target_register_id", { length: 36 }).references(() => registers.id, { onDelete: "set null" }),
    targetRegisterName: varchar("target_register_name", { length: 160 }),
    filename: varchar("filename", { length: 255 }).notNull(),
    mimeType: varchar("mime_type", { length: 120 }),
    fileSize: int("file_size").notNull().default(0),
    checksum: varchar("checksum", { length: 64 }),
    chunkCount: int("chunk_count").notNull().default(0),
    chunkSize: int("chunk_size").notNull().default(0),
    sheetName: varchar("sheet_name", { length: 160 }),
    headerRow: int("header_row").notNull().default(1),
    mapping: json("mapping"),
    strategy: json("strategy"),
    rowsTotal: int("rows_total").notNull().default(0),
    rowsImported: int("rows_imported").notNull().default(0),
    rowsUpdated: int("rows_updated").notNull().default(0),
    rowsSkipped: int("rows_skipped").notNull().default(0),
    rowsRejected: int("rows_rejected").notNull().default(0),
    duplicatesFound: int("duplicates_found").notNull().default(0),
    progress: int("progress").notNull().default(0),
    errorMessage: text("error_message"),
    cancelRequested: boolean("cancel_requested").notNull().default(false),
    createdByUserId: varchar("created_by_user_id", { length: 36 }).references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    startedAt: datetime("started_at", { mode: "date", fsp: 3 }),
    finishedAt: datetime("finished_at", { mode: "date", fsp: 3 }),
    updatedAt: updatedAt(),
  },
  (table) => [
    index("import_jobs_status_idx").on(table.status, table.createdAt),
    index("import_jobs_creator_idx").on(table.createdByUserId),
  ],
);

export const importChunks = mysqlTable(
  "import_chunks",
  {
    id: id(),
    jobId: varchar("job_id", { length: 36 })
      .notNull()
      .references(() => importJobs.id, { onDelete: "cascade" }),
    chunkIndex: int("chunk_index").notNull(),
    /** LONGBLOB: one chunk of the uploaded workbook (assembled on import). */
    data: longBlob("data").notNull(),
    createdAt: createdAt(),
  },
  (table) => [
    uniqueIndex("import_chunks_job_index_unique").on(table.jobId, table.chunkIndex),
  ],
);

export const importErrors = mysqlTable(
  "import_errors",
  {
    id: id(),
    jobId: varchar("job_id", { length: 36 })
      .notNull()
      .references(() => importJobs.id, { onDelete: "cascade" }),
    rowNumber: int("row_number").notNull(),
    columnName: varchar("column_name", { length: 160 }),
    code: varchar("code", { length: 64 }).notNull(),
    message: varchar("message", { length: 600 }).notNull(),
    severity: mysqlEnum("severity", ["error", "warning"]).notNull().default("error"),
    createdAt: createdAt(),
  },
  (table) => [index("import_errors_job_idx").on(table.jobId, table.rowNumber)],
);

export const auditLogs = mysqlTable(
  "audit_logs",
  {
    id: id(),
    actorUserId: varchar("actor_user_id", { length: 36 }).references(() => users.id, { onDelete: "set null" }),
    actorEmail: varchar("actor_email", { length: 255 }),
    action: varchar("action", { length: 80 }).notNull(),
    entityType: varchar("entity_type", { length: 60 }).notNull(),
    entityId: varchar("entity_id", { length: 64 }),
    registerId: varchar("register_id", { length: 64 }),
    summary: varchar("summary", { length: 400 }),
    metadata: json("metadata"),
    ip: varchar("ip", { length: 64 }),
    requestId: varchar("request_id", { length: 64 }),
    createdAt: createdAt(),
  },
  (table) => [
    index("audit_logs_created_idx").on(table.createdAt),
    index("audit_logs_entity_idx").on(table.entityType, table.entityId),
    index("audit_logs_actor_idx").on(table.actorUserId, table.createdAt),
  ],
);

export const settings = mysqlTable("settings", {
  key: varchar("key", { length: 80 }).primaryKey(),
  value: text("value").notNull(),
  updatedAt: updatedAt(),
});

export const rateLimits = mysqlTable("rate_limits", {
  bucket: varchar("bucket", { length: 190 }).primaryKey(),
  windowStart: datetime("window_start", { mode: "date", fsp: 3 }).notNull(),
  count: int("count").notNull().default(0),
});

/* ------------------------------- relations ------------------------------- */

export const usersRelations = relations(users, ({ many }) => ({
  sessions: many(sessions),
  invitations: many(invitations),
}));

export const sessionsRelations = relations(sessions, ({ one }) => ({
  user: one(users, { fields: [sessions.userId], references: [users.id] }),
}));

export const registersRelations = relations(registers, ({ many }) => ({
  fields: many(registerFields),
  records: many(records),
}));

export const registerFieldsRelations = relations(registerFields, ({ one }) => ({
  register: one(registers, {
    fields: [registerFields.registerId],
    references: [registers.id],
  }),
}));

export const recordsRelations = relations(records, ({ one, many }) => ({
  register: one(registers, { fields: [records.registerId], references: [registers.id] }),
  values: many(recordValues),
}));

export const recordValuesRelations = relations(recordValues, ({ one }) => ({
  record: one(records, { fields: [recordValues.recordId], references: [records.id] }),
  field: one(registerFields, {
    fields: [recordValues.fieldId],
    references: [registerFields.id],
  }),
}));

export const importJobsRelations = relations(importJobs, ({ many }) => ({
  chunks: many(importChunks),
  errors: many(importErrors),
}));

export const importChunksRelations = relations(importChunks, ({ one }) => ({
  job: one(importJobs, { fields: [importChunks.jobId], references: [importJobs.id] }),
}));

export const importErrorsRelations = relations(importErrors, ({ one }) => ({
  job: one(importJobs, { fields: [importErrors.jobId], references: [importJobs.id] }),
}));

/* -------------------------------- helpers -------------------------------- */

export function uuid(): string {
  return crypto.randomUUID();
}

/* ---------------------------- inferred types ----------------------------- */

export type User = typeof users.$inferSelect;
export type NewUser = typeof users.$inferInsert;
export type SessionRow = typeof sessions.$inferSelect;
export type PasswordResetTokenRow = typeof passwordResetTokens.$inferSelect;
export type Invitation = typeof invitations.$inferSelect;
export type Register = typeof registers.$inferSelect;
export type RegisterField = typeof registerFields.$inferSelect;
export type RegisterViewRow = typeof registerViews.$inferSelect;
export type RegisterAccessRow = typeof registerAccess.$inferSelect;
export type RecordRow = typeof records.$inferSelect;
export type RecordValueRow = typeof recordValues.$inferSelect;
export type ImportJob = typeof importJobs.$inferSelect;
export type ImportErrorRow = typeof importErrors.$inferSelect;
export type AuditLog = typeof auditLogs.$inferSelect;
export type SettingRow = typeof settings.$inferSelect;
